{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Naltrexone, the closest structural analogue (Morgan 0.61), showed oral bioavailability of only ~5% in healthy male volunteers due to extensive first-pass metabolism; the query is its quaternary N-methyl analogue, which should be even less orally absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Another naltrexone study estimated systemic bioavailability of a single oral dose at only 5–6% in healthy volunteers, reinforcing that the closest analogue family has low oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Morphine-6-glucuronide, a highly polar opioid derivative, has poor oral bioavailability, supporting the expectation that the permanently charged quaternary ammonium query will also be poorly absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nalmefene, a related tertiary-amine opioid antagonist, had an absolute oral bioavailability of 41% in humans; this is high-F evidence but is less transferable because the query's quaternary ammonium is much more polar and membrane-impermeable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted low: the query is methylnaltrexone, a quaternary ammonium naltrexone derivative. The closest analogue naltrexone has predominantly low oral bioavailability (5–10%), and the permanent positive charge should further reduce permeability and oral absorption. Higher-F analogues such as nalmefene are tertiary amines and less transferable.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability record for methylnaltrexone was retrieved.",
    "Naltrexone itself has variable reported oral bioavailability (5–60%), though most direct measurements are low.",
    "No permeability or efflux data specific to the quaternary ammonium query were available in the evidence set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

